
const $=s=>document.querySelector(s);
const icons={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',bolt:'<path d="m13 2-8 12h7l-1 8 8-12h-7z"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',flag:'<path d="M5 21V3m0 0h14l-3 5 3 5H5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',star:'<path d="m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1z"/>',book:'<path d="M12 5C8 2 4 3 3 4v16c3-2 6-2 9 0 3-2 6-2 9 0V4c-3-2-6-2-9 1v15"/>',cube:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5zm0 9 9-4m-9 4L3 8m9 4v10"/>',spark:'<path d="m12 3 2 7 7 2-7 2-2 7-2-7-7-2 7-2z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const ico=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.cube}</svg>`;
const pill=(t,c='')=>`<span class="pill ${c}">${t}</span>`;
const btn=(t,act,primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${act}">${t}</button>`;
const cmd=t=>`<div class="command">${ico('bolt')}<code>${t}</code><button type="button" class="iconbtn" data-copy="${t}" aria-label="Copiar ${t}">${ico('copy')}</button></div>`;
const routes=[['inicio','Inicio'],['tablero','Tablero'],['portfolio','Portfolio'],['propuestas','Propuestas'],['logros','Logros'],['documentacion','Documentación']];
const titles={...Object.fromEntries(routes),configuracion:'Configuración',idea:'PandaSaga'};

function proposals(){return head('Propuestas','Lo que la fábrica propone mejorar. Tú decides el siguiente paso.')+tabbar(['Memoria','Backlog'],tab==='Backlog'?'Backlog':'Memoria','section')+(tab==='Backlog'?section('Backlog de la fábrica',`<div class="row between sectiontitle">${pill('65 abiertos')}<span class="small muted">Prioridad → identificador</span></div>${['Consolidar señales de estado','Revisar el flujo de documentación','Reducir duplicación en contratos'].map((x,i)=>`<button class="listrow" data-action="backlog"><span class="mono muted">BL · ${i+1}</span><div><strong>${x}</strong><p>Ejemplo visual · abierto</p></div>${ico('arrow')}</button>`).join('')}<details class="accordion"><summary>Ver hechos y descartados</summary><p>El historial sigue accesible.</p></details>${cmd('/pandacorp:implement-backlog')}`):`<div class="stats">${[['Notas sin refinar','1001','pendientes de cosecha'],['Candidatas','250','esperan corroboración'],['Promociones','11','listas para revisar'],['Última cosecha','15 oct','2026 · fecha absoluta']].map(([a,b,c])=>`<div class="stat"><span class="small muted">${a}</span><div class="number">${b}</div><small>${c}</small></div>`).join('')}</div><div class="homegrid">${section('Lecciones candidatas',`<div class="stack">${['Un único prototipo canónico evita referencias cruzadas','Un modelo de datos debe indicar su fuente','Un cambio debe conservar su contexto'].map((x,i)=>`<button class="listrow" data-action="lesson"><span class="iconbox">${ico('book')}</span><div><strong>${x}</strong><p>Ejemplo · esperando corroboración</p></div>${ico('arrow')}</button>`).join('')}</div>${cmd('/pandacorp:memory review')}`)}<div class="stack">${section('Siguiente paso',`<p>Refinar notas del taller antes de promover conocimiento.</p>${cmd('/pandacorp:memory harvest')}`)}${section('Promociones y poda',`<p>Los streams conservan detalle, ocultar, ver más y comandos de revisión.</p><button class="link" data-action="lesson">Ver una propuesta ${ico('arrow')}</button>`)}</div></div>`)}
function achievements(){if(tab==='Estadísticas')return head('Logros','El progreso que has construido, con evidencia detrás.')+tabbar(['Resumen','Misiones','Trofeos','Estadísticas','Rangos'],tab,'section')+visualStats();const active=['Resumen','Misiones','Trofeos','Estadísticas','Rangos'].includes(tab)?tab:'Resumen';return head('Logros','El progreso que has construido, con evidencia detrás.')+tabbar(['Resumen','Misiones','Trofeos','Estadísticas','Rangos'],active,'section')+(active==='Resumen'?`<div class="stack"><section class="panel hero"><div class="medal">20</div><div class="spacer"><span class="eyebrow">Gremio Pandacorp · nivel 20</span><h2>Portador de Luz II</h2><p>31 hazañas · 19 de 82 trofeos</p><div class="track"><span style="width:40%"></span></div><small class="muted">1930 / 2040 XP · 110 para el siguiente nivel</small></div></section><div class="twocol">${section('Próximas hazañas',`<div class="stack"><div><div class="row between"><strong>El fordismo digital</strong><span class="small muted">52%</span></div><p class="small">Work orders completados</p><div class="track" style="margin-top:var(--s3)"><span style="width:52%"></span></div></div><div><div class="row between"><strong>Cirujano de ideas</strong><span class="small muted">46%</span></div><p class="small">Ideas descartadas</p><div class="track" style="margin-top:var(--s3)"><span style="width:46%"></span></div></div></div>`)}${section('Vitrina del gremio',`<div class="row trophy"><span class="iconbox amber">${ico('flag')}</span><div><strong>El primer ladrillo</strong><p class="small">PersonalPage v2 · 7 oct 2026</p></div></div><div class="row trophy"><span class="iconbox">${ico('cube')}</span><div><strong>El blueprintero</strong><p class="small">Tu arquitectura tomó forma</p></div></div>`)}</div></div>`:active==='Rangos'?section('Rangos',`<div class="stack">${['Buscador del Alba','Portador de Luz II · tu rango','Guardián del Éter'].map((x,i)=>`<div class="listrow"><span class="iconbox ${i===1?'':'amber'}">${ico('shield')}</span><div><strong>${x}</strong><p>${i===1?'Alcanzado · nivel actual':'Escala ilustrativa · consulta requisitos'}</p></div></div>`).join('')}</div>`):section(active,`<div class="stack">${active==='Estadísticas'?'<div class="row pulse"><div><div class="number">1</div><small>Lanzado</small></div><div><div class="number">31</div><small>Hazañas</small></div></div><p>Informe, categorías, fuentes y sellos de frescura mantienen su contenido.</p>':`<div class="toolbar">${btn('Todos','category')}${btn('Descubrimiento','category')}${btn('Calidad','category')}</div><div class="trophy"><span class="iconbox amber">${ico('flag')}</span><div><strong>${active==='Misiones'?'La aventura continúa':'El primer ladrillo'}</strong><p>Progreso, requisitos, rareza y fecha permanecen visibles.</p></div></div><details class="accordion"><summary>Secretos y próximos desbloqueos</summary><p>Las revelaciones son accesibles con toque y teclado.</p></details>`}</div>`))}
function configuration(){const active=['Habilidades','Agentes','Reglas de decisión','Estándares'].includes(tab)?tab:'Habilidades';return head('Configuración','Las capacidades y reglas de tu fábrica, a la vista.')+tabbar(['Habilidades','Agentes','Reglas de decisión','Estándares'],active,'section')+(active==='Agentes'?section('Equipo de agentes',`<div class="twocol">${[['architect','Arquitecto'],['designer','Diseñador'],['frontend-dev','Frontend'],['backend-dev','Backend'],['reviewer','Reviewer'],['test-writer','Tests']].map(([a,t])=>`<button type="button" class="listrow" data-action="agent"><img class="agent" src="assets/${a}.png" alt=""><div><strong>${t}</strong><p>Rol, modelo, nivel y habilidades relacionadas</p></div>${ico('arrow')}</button>`).join('')}</div>`):section(active,`<div class="stack">${(active==='Habilidades'?['/pandacorp:explore','/pandacorp:spec','/pandacorp:design','/pandacorp:architecture','/pandacorp:change']:active==='Reglas de decisión'?['Decisiones humanas','Documentación y trazabilidad','Una fuente de verdad']:['Accesibilidad','Calidad y pruebas','Convenciones de código']).map(t=>`<button type="button" class="listrow" data-action="reference"><span class="iconbox">${ico(active==='Habilidades'?'bolt':'shield')}</span><div><strong>${t}</strong><p>Resumen breve; abre el detalle para leer la definición completa.</p></div>${ico('arrow')}</button>`).join('')}</div>`))}

const snapshot=window.MC_SNAPSHOT;
if(!snapshot?.projects?.length)throw new Error('Falta la captura local: genera data/snapshot.js antes de abrir la maqueta.');
const projects=snapshot.projects, ideas=snapshot.ideas;
const phaseLabels={product:'Producto',design:'Diseño',architecture:'Arquitectura',implementation:'Construcción',release:'Release'};
const stateNames={todo:'Planificado',in_progress:'En curso',review:'En revisión',done:'Verificado',fail:'Bloqueado'};
const stateTones={todo:'',in_progress:'lilac',review:'amber',done:'green',fail:'red'};
let page='inicio',tab='Resumen',obs='Línea de tiempo',model='Diagrama',openDialogTrigger;
let projectId='pandasaga',ideaSlug=projects.find(p=>p.id==='pandasaga')?.idea?.slug||ideas[0].slug;
let docId='',woId='',woView='Resumen',woFrd='',woState='',docQuery='',modelQuery='',modelScale=1,modelSelected='',boardQuery='',boardCategory='',manualDoc='';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const projectName=p=>p.name.split(' — ')[0].replace('Pandacorp (Mission Control)','Mission Control');
const initial=p=>projectName(p).split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const selectedProject=()=>projects.find(p=>p.id===projectId)||projects[0];
const selectedIdea=()=>ideas.find(i=>i.slug===ideaSlug)||ideas[0];
const contextProject=()=>page==='idea'?projects.find(p=>p.id===selectedIdea().projectId)||null:selectedProject();
const pct=p=>p.counts.orders?Math.round(p.counts.done/p.counts.orders*100):0;
const captureTime=new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(snapshot.capturedAt));
const stamp=()=>`<div class="snapshot-label">Captura local · ${esc(captureTime)} · documentos reales, lectura de solo consulta</div>`;
const head=(title,sub,action='')=>`<div class="pagehead"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action}</div>`;
const section=(title,content,action='',id='',style=null)=>{const known={'arch-stack':['blue','cube'],'arch-services':['teal','bolt'],'arch-model':['teal','cube'],'arch-adrs':['amber','shield']};const t=style||known[id];return `<section ${id?`id="${esc(id)}"`:''} class="panel ${t?'semantic-panel':''} ${t?.[2]||''}" ${t?`data-tone="${t[0]}"`:''}><div class="row between sectiontitle"><h2>${t?`<span class="section-icon">${ico(t[1])}</span>`:''}${esc(title)}</h2>${action}</div>${content}</section>`};
const empty=t=>`<div class="status-empty">${esc(t)}</div>`;
const rich=html=>`<div class="rich">${html||'<p>No hay contenido publicado en esta captura.</p>'}</div>`;
const documentTypes={product:{tone:'blue',icon:'flag',label:'Producto'},research:{tone:'teal',icon:'search',label:'Research'},contract:{tone:'violet',icon:'book',label:'Contrato funcional'},design:{tone:'pink',icon:'spark',label:'Diseño'},architecture:{tone:'amber',icon:'cube',label:'Arquitectura'},order:{tone:'blue',icon:'bolt',label:'Work order'},decision:{tone:'amber',icon:'shield',label:'Decisión técnica'},reference:{tone:'slate',icon:'book',label:'Referencia'}};
function docType(d){const path=(d?.relPath||'').toLowerCase();return /work-orders/.test(path)?'order':/research/.test(path)?'research':/\/adr\//.test(path)?'decision':/blueprint|architecture|data-model/.test(path)?'architecture':/fdd\.md|design|\/mocks\//.test(path)?'design':/\/frd\.md/.test(path)?'contract':/prd\.md|\/product\//.test(path)?'product':'reference'}
function typeBadge(type){const t=documentTypes[type]||documentTypes.reference;return `<span class="type-badge" data-tone="${t.tone}">${ico(t.icon)}${t.label}</span>`}
function blockStyle(label){if(/problema/i.test(label))return['coral','flag'];if(/hipótesis|valor|diferenciador/i.test(label))return['green','spark'];if(/métrica|éxito/i.test(label))return['teal','bolt'];if(/decisi/i.test(label))return['amber','shield'];if(/fuera/i.test(label))return['slate','flag'];if(/^alcance/i.test(label))return['blue','check','spec-scope'];if(/hallazgo|referente|research/i.test(label))return['teal','search'];return['blue','book']}
const docGroupTone=group=>group.startsWith('Feature:')?'violet':({Design:'pink',Product:'blue',Analytics:'teal','Work orders':'blue',Reviews:'amber',Rules:'slate',Global:'slate'})[group]||'slate';
const phaseTone=phase=>({product:'blue',design:'pink',architecture:'amber',implementation:'violet',release:'green',discovered:'teal'})[phase]||'slate';
const stateTone=state=>({todo:'slate',in_progress:'blue',review:'amber',done:'green',fail:'coral'})[state]||'slate';
const documentButton=(id,label,kind='doc')=>{const d=contextProject()?.docs.find(d=>d.id===id),t=documentTypes[docType(d)];return `<button type="button" class="btn outline doc-button" data-tone="${t.tone}" data-${kind}="${esc(id)}">${ico(t.icon)}${esc(label)}</button>`};
const getDoc=(p,path)=>p.docs.find(d=>d.relPath===path)||null;
const sourceFooter=(p,path,label='Leer documento completo')=>{const d=getDoc(p,path);return d?`<div class="sourcefoot"><span>${esc(path)}</span>${documentButton(d.id,label)}</div>`:''};
function navUrl(screen,patch={}){const u=new URLSearchParams();const v={project:projectId,idea:ideaSlug,tab,doc:docId,wo:woId,woview:woView,model,obs,...patch};for(const [k,value]of Object.entries(v))if(value&&['portfolio','idea'].includes(screen))u.set(k,value);return '#'+screen+(u.size?'?'+u.toString():'')}
function go(screen,patch={}){const next=navUrl(screen,patch);if(location.hash===next)render();else location.hash=next}
function switchTab(value){go(page,{tab:value,doc:'',wo:''})}
function tabbar(items,active,kind='tab'){const tones={Resumen:['slate','cube'],Spec:['blue','book'],'Work orders':['blue','bolt'],Arquitectura:['amber','cube'],Cambios:['pink','flag'],Party:['green','spark'],Observabilidad:['teal','clock'],Documentos:['teal','book'],Comandos:['violet','bolt'],Propuesta:['blue','flag'],Campaña:['green','flag']};return `<div class="tabbar" aria-label="Secciones"><span class="sr-only"></span>${items.map(t=>`<button type="button" aria-pressed="${t===active}" data-tone="${tones[t]?.[0]||'violet'}" data-${kind}="${esc(t)}">${tones[t]?ico(tones[t][1]):''}${esc(t)}</button>`).join('')}</div>`}
function snapshotBadge(p){return pill(phaseLabels[p.phase]||p.phase,phaseTone(p.phase))}
function picker(p){return `<button type="button" class="project-picker" data-action="projects" aria-haspopup="dialog"><span class="projectavatar" data-tone="${phaseTone(p.phase)}">${esc(initial(p))}</span><span><strong>${esc(projectName(p))}</strong><small>${esc(phaseLabels[p.phase]||p.phase)} · ${p.counts.orders?p.counts.done+'/'+p.counts.orders+' WO':'Plan aún sin work orders'}</small></span><span aria-hidden="true">⌄</span></button>`}
function openPicker(){const p=selectedProject();dialog('Cambiar proyecto',`<div class="project-list"><label class="field">${ico('search')}<input id="project-search" type="search" placeholder="Buscar proyecto…" aria-label="Buscar proyecto" autocomplete="off"></label><div id="project-options">${projects.map(x=>`<button type="button" class="project-option" data-pick-project="${esc(x.id)}" data-project-match="${esc(x.name.toLowerCase())}" aria-current="${x.id===p.id}"><span class="projectavatar" data-tone="${phaseTone(x.phase)}">${esc(initial(x))}</span><span><strong>${esc(projectName(x))}</strong><small>${esc(phaseLabels[x.phase]||x.phase)} · ${x.counts.docs} documentos · ${x.counts.frds} FRDs · ${x.counts.orders?x.counts.done+'/'+x.counts.orders+' WO':'sin WOs publicados'}</small><span class="track"><span style="width:${pct(x)}%"></span></span></span><span aria-hidden="true">${x.id===p.id?'✓':'→'}</span></button>`).join('')}</div></div>`);$('#project-search').focus()}
function portfolio(){const p=selectedProject();return head('Portfolio','Elige un proyecto y recorre su documentación, arquitectura y construcción.')+stamp()+`<div class="contextbar">${picker(p)}<span class="spacer"></span>${snapshotBadge(p)}${pill(p.version?'v'+String(p.version).replace(/^v/,''):'Versión no indicada')}<div class="progress"><small class="muted">${p.counts.done} / ${p.counts.orders} work orders${p.counts.orders?' · '+pct(p)+'%':''}</small><div class="track" style="margin-top:var(--s2)"><span style="width:${pct(p)}%"></span></div></div></div>${tabbar(['Resumen','Spec','Work orders','Arquitectura','Cambios','Party','Observabilidad','Documentos','Comandos'],tab)}<div class="app-reading">${workspaceBody(tab,p)}</div>`}
function home(){return head('Inicio','Lo que necesita tu atención. Lo que sigue avanzando.',pill('Captura de tus proyectos','green'))+stamp()+`<div class="homegrid"><div class="stack">${section('Tu cartera',projects.map(p=>`<a href="${navUrl('portfolio',{project:p.id,tab:'Resumen'})}" class="projectrow" style="display:block"><div class="projectline"><span class="projectavatar" data-tone="${phaseTone(p.phase)}">${esc(initial(p))}</span><div><strong>${esc(projectName(p))}</strong><p class="small">${p.counts.frds} FRDs · ${p.counts.docs} documentos</p><div class="track" style="margin-top:var(--s3)"><span style="width:${pct(p)}%"></span></div></div>${snapshotBadge(p)}</div></a>`).join(''))}${section('Tu siguiente revisión',`<div class="turnrow"><span class="iconbox">${ico('cube')}</span><div><h3>PandaSaga · arquitectura</h3><p>Stack, integraciones, modelo y plan con sus documentos completos.</p></div><a class="btn primary" href="${navUrl('portfolio',{project:'pandasaga',tab:'Arquitectura'})}">Abrir arquitectura</a></div><div class="turnrow"><span class="iconbox">${ico('book')}</span><div><h3>Spec de Funko Tracker</h3><p>Lee el producto, la investigación y sus funcionalidades.</p></div><a class="btn" href="${navUrl('portfolio',{project:'funko-tracker',tab:'Spec'})}">Abrir Spec</a></div>`)} </div><div class="stack">${section('Pulso de la captura',`<div class="pulse"><div><div class="number">${projects.length}</div><small>Proyectos</small></div><div><div class="number">${projects.reduce((n,p)=>n+p.counts.frds,0)}</div><small>FRDs</small></div><div><div class="number">${projects.reduce((n,p)=>n+p.counts.done,0)}</div><small>WO verificados</small></div></div><p class="small">Contados desde los archivos al preparar esta ronda.</p>`)}${section('Ideas en el tablero',`<div class="row between"><strong>${ideas.filter(x=>x.status!=='discarded').length} ideas activas</strong><a class="link" href="#tablero">Ver tablero ${ico('arrow')}</a></div><p class="small">Cada proyecto conserva el mismo contenido al entrar por su idea.</p>`)}${section('Recorrido sugerido',`<ol class="rich"><li>Abre PandaSaga desde el Tablero.</li><li>Recorre Spec, Arquitectura y Documentos.</li><li>En Portfolio cambia a Mission Control para ver sus work orders y luego a otro proyecto.</li><li>Compara escritorio, tablet y móvil.</li></ol>`)}</div></div>`}
function boardPhase(i){if(i.status==='discarded')return'discarded';const p=projects.find(p=>p.id===i.projectId);return p?p.phase:i.status==='shipped'?'release':'discovered'}
function ideaCard(i){return `<article class="idea" data-idea="${esc((i.title+' '+i.body).toLowerCase())}" data-category="${esc(i.category||'')}"><button type="button" class="star" aria-label="Favorita: ${esc(i.title)}" aria-pressed="${!!i.favorite}" data-star="${esc(i.slug)}">${i.favorite?'★':ico('star')}</button><a href="${navUrl('idea',{idea:i.slug,tab:projects.find(p=>p.id===i.projectId)?.architecture?'Arquitectura':projects.find(p=>p.id===i.projectId)?.spec?'Spec':'Propuesta',doc:'',wo:''})}">${esc(i.title)}</a><div class="meta">${pill(esc(i.category||'Sin categoría'))}${pill(esc(i.return||'Sin retorno definido'),'lilac')}<span class="spacer"></span><span class="muted">${i.score!=null?'Score '+esc(i.score):'Sin score'}</span></div></article>`}
function board(){const cols=[['discovered','Investigación'],['product','Producto'],['design','Diseño'],['architecture','Arquitectura'],['implementation','Construcción'],['release','Release']];return head('Tablero','Todas tus ideas, con el contenido completo de sus proyectos.',btn('+ Capturar ideas','capture',true))+stamp()+`<div class="toolbar"><label class="field">${ico('search')}<input id="idea-search" type="search" aria-label="Buscar ideas" placeholder="Buscar por nombre o contenido…" value="${esc(boardQuery)}"></label><label class="field"><select id="idea-category" aria-label="Filtrar por categoría"><option value="">Todas las categorías</option>${[...new Set(ideas.map(i=>i.category).filter(Boolean))].map(c=>`<option ${c===boardCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></label><button class="btn ghost" type="button" data-action="clear-board">Limpiar</button><span class="spacer"></span>${btn('Ver descartadas ('+ideas.filter(i=>i.status==='discarded').length+')','discarded')}</div><div class="board">${cols.map(([id,name],n)=>`<section class="column" data-tone="${phaseTone(id)}"><h2 class="colhead row between"><span><span class="muted">${n+1} · </span>${name}</span>${pill(ideas.filter(i=>boardPhase(i)===id).length)}</h2>${ideas.filter(i=>boardPhase(i)===id).map(ideaCard).join('')||'<div class="empty small">Sin ideas en esta fase</div>'}</section>`).join('')}</div>`}
function idea(){const i=selectedIdea(),p=contextProject();const available=['Propuesta',...(p?.spec?['Spec']:[]),...(p?['Arquitectura','Documentos','Campaña']:[])];const active=available.includes(tab)?tab:'Propuesta';return head(i.title,p?.subtitle||'Propuesta de la base de ideas.','<a class="link" href="#tablero">← Volver al tablero</a>')+stamp()+`<div class="row wrap board-status">${pill(esc(i.category||'Idea'))}${pill(esc(i.return||'Sin retorno definido'))}${pill(i.score!=null?'Score '+i.score:'Sin score')}${p?snapshotBadge(p):''}${p?`<a class="link" href="${navUrl('portfolio',{project:p.id,tab:['Spec','Arquitectura','Documentos'].includes(active)?active:'Resumen'})}">Abrir en Portfolio ${ico('arrow')}</a>`:''}</div>${tabbar(available,active)}${active==='Propuesta'?section('Propuesta',rich(i.html)):active==='Spec'?specView(p):active==='Arquitectura'?architecture(p):active==='Documentos'?documentReader(p):campaign(p)}`}
function summaryView(p){return `<div class="stack">${section('Estado del proyecto',`<div class="row between wrap"><strong>${esc(phaseLabels[p.phase]||p.phase)}</strong>${pill(p.running?'Construcción activa':'Sin construcción activa',p.running?'green':'')}</div><p style="margin-top:var(--s3)">${esc(p.subtitle)}</p><div class="summary-strip"><div data-tone="violet"><strong>${p.counts.frds}</strong><small>FRDs publicados</small></div><div data-tone="blue"><strong>${p.counts.docs}</strong><small>Documentos</small></div><div data-tone="green"><strong>${p.counts.done}/${p.counts.orders}</strong><small>WO verificados</small></div><div data-tone="amber"><strong>${p.adrs.length}</strong><small>Decisiones técnicas</small></div></div><div class="row wrap">${btn('Ver Spec','open-spec')}${btn('Ver Arquitectura','open-architecture')}${btn('Ver Work orders','open-orders')}</div>`)}${p.idea?section('Contexto del producto',rich(p.idea.html)):getDoc(p,'docs/product/prd.md')?section('Documento de producto',rich(getDoc(p,'docs/product/prd.md').html)):empty('No hay resumen de producto publicado.')}${section('Decisiones del proyecto',p.decisions?.length?p.decisions.map(d=>`<div class="item-action"><span><strong>${esc(d.title)}</strong><small>${esc(d.date||'Sin fecha')} · ${esc(d.recommendation||'')}</small></span>${pill(d.resolved?'Resuelta':'Pendiente',d.resolved?'green':'amber')}</div>`).join(''):'<p class="small">Sin decisiones pendientes publicadas en esta captura.</p>')}${section('Actividad registrada',activityView(p))}</div>`}
function specView(p){if(!p)return empty('Esta idea todavía no tiene proyecto.');const data=p.spec?.parsed;const productDoc=getDoc(p,'docs/product/prd.md');if(!data?.hasContent)return `<div class="stack">${section('Spec',`<p>No hay un resumen de Spec publicado para este proyecto. Puedes consultar su PRD y todos los FRDs reales.</p>${productDoc?sourceFooter(p,productDoc.relPath,'Leer PRD completo'):''}`,'','',['blue','book'])}${featureCatalog(p,null)}</div>`;return `<div class="stack spec-view"><section class="spec-lead" data-tone="blue"><div class="lead-label">${ico('book')}<span>SPEC · ${esc(projectName(p))}</span></div><h2>La visión del producto</h2><p>${esc(data.intro||p.subtitle)}</p><nav class="section-links" aria-label="Contenido de Spec"><a data-tone="blue" href="#spec-prd" data-scroll="spec-prd">${ico('flag')}Producto</a><a data-tone="teal" href="#spec-research" data-scroll="spec-research">${ico('search')}Research</a><a data-tone="violet" href="#spec-frds" data-scroll="spec-frds">${ico('book')}${p.counts.frds} FRDs</a></nav></section>${[data.prd,data.research].filter(Boolean).map((area,n)=>`<section id="${n===0?'spec-prd':'spec-research'}" class="spec-area" data-tone="${n===0?'blue':'teal'}"><div class="row between sectiontitle"><h2 class="area-title"><span class="section-icon">${ico(n===0?'flag':'search')}</span>${esc(area.label==='PRD'?'Producto':area.label)}</h2>${documentButton(getDoc(p,n===0?'docs/product/prd.md':'docs/product/research.md')?.id||'','Documento completo')}</div><div class="content-grid">${area.blocks.map(block=>section(block.label,`<div class="spec-block">${rich(block.html||'<p>'+esc(block.markdown)+'</p>')}</div>`,'','',blockStyle(block.label))).join('')}</div></section>`).join('')}${featureCatalog(p,data.frds)}</div>`}
function frdGroups(p){return [...new Set(p.docs.filter(d=>/^docs\/frds\/frd-\d+[^/]*\/frd\.md$/.test(d.relPath)).map(d=>d.relPath.split('/')[2]))].sort()}
function featureCatalog(p,parsed){return `<section id="spec-frds" data-tone="violet"><div class="row between sectiontitle"><h2 class="area-title"><span class="section-icon">${ico('book')}</span>Funcionalidades · ${p.counts.frds} FRDs</h2><span class="small muted">Todos los contratos publicados</span></div><div class="content-grid">${frdGroups(p).map(group=>{const id=group.match(/^frd-\d+/)[0].toUpperCase(),f=parsed?.find(f=>f.id===id),doc=getDoc(p,'docs/frds/'+group+'/frd.md'),blue=getDoc(p,'docs/frds/'+group+'/blueprint.md'),fdd=getDoc(p,'docs/frds/'+group+'/fdd.md'),orders=p.orders.filter(w=>w.frd===group),done=orders.filter(w=>w.state==='done').length;return `<article class="feature-card" data-tone="violet"><div class="row between wrap"><span class="type-badge" data-tone="violet">${ico('book')}<span class="mono">${id}</span></span>${orders.length?`<span class="feature-progress" data-tone="${done===orders.length?'green':'slate'}">${ico(done===orders.length?'check':'clock')}${done}/${orders.length} WO verificados</span>`:''}</div><h3>${esc(f?.title||group.replace(/^frd-\d+-/,'').replaceAll('-',' '))}</h3>${f?.summary?`<p>${esc(f.summary)}</p>`:''}<div class="row">${doc?documentButton(doc.id,'Contrato'):''}${fdd?documentButton(fdd.id,'Diseño'):''}${blue?documentButton(blue.id,'Blueprint'):''}${orders.length?`<button type="button" class="btn doc-button" data-tone="blue" data-frd-orders="${esc(group)}">${ico('bolt')}Work orders</button>`:''}</div></article>`}).join('')}</div></section>`}
function architecture(p){if(!p)return empty('Esta idea todavía no tiene documentos de arquitectura.');const a=p.architecture?.parsed,doc=getDoc(p,'docs/product/architecture.md');return `<div class="stack">${a?.intro?`<div class="hintbox architecture-intro" data-tone="amber">${esc(a.intro)}</div>`:''}<nav class="section-links architecture-links" aria-label="Contenido de arquitectura">${[['arch-stack','Stack'],['arch-services','Integraciones y operación'],['arch-model','Modelo de datos'],['arch-adrs','Decisiones'],['arch-plan','Plan y documentos']].map(([id,label])=>`<a data-tone="${({'arch-stack':'blue','arch-services':'teal','arch-model':'teal','arch-adrs':'amber','arch-plan':'violet'})[id]}" href="#${id}" data-scroll="${id}">${ico(id==='arch-adrs'?'shield':'cube')}${label}</a>`).join('')}</nav>${section('Stack y tecnologías',a?.stackRows?.length?`<table class="data-table"><thead><tr><th>Capa</th><th>Elección</th><th>Por qué</th></tr></thead><tbody>${a.stackRows.map(r=>`<tr><td>${esc(r.capa)}</td><td>${esc(r.eleccion)}</td><td>${esc(r.porque)}</td></tr>`).join('')}</tbody></table>${a.host||a.coste?`<div class="row wrap" style="margin-top:var(--s4)">${a.host?pill(esc(a.host)):''}${a.coste?pill(esc(a.coste),'green'):''}</div>`:''}${sourceFooter(p,'docs/product/architecture.md','Arquitectura completa')}`:doc?`<p>La arquitectura está publicada en el documento técnico. Este proyecto no tiene un resumen adicional.</p>${sourceFooter(p,doc.relPath,'Abrir arquitectura completa')}`:empty('La arquitectura todavía no está publicada en los archivos de este proyecto.'),'','arch-stack')}${section('Integraciones y operación',a?.services?.length?a.services.map(s=>`<div class="service"><h3>${esc(s.title)}</h3><p>${esc(s.desc)}</p></div>`).join(''):empty('No hay un resumen de integraciones publicado. Consulta el documento de arquitectura si está disponible.'),'','arch-services')}${section('Modelo de datos',modelView(p),'','arch-model')}${section('Variables de entorno',p.envNames.length?`<p class="small">Nombres documentados. Esta captura no contiene valores.</p><div class="row wrap" style="margin-top:var(--s4)">${p.envNames.map(n=>`<span class="pill mono">${esc(n)}</span>`).join('')}</div>`:empty('No hay variables documentadas en la captura.'))}${section('Decisiones de arquitectura',p.adrs.length? p.adrs.map(adr=>{const d=p.docs.find(d=>d.relPath.startsWith('docs/adr/')&&(d.body===adr.body||d.relPath.toLowerCase().includes(String(adr.id).toLowerCase())));return `<button type="button" class="item-action" ${d?`data-doc="${esc(d.id)}"`:`data-adr="${esc(adr.id)}"`}><span><strong>${esc(adr.title||adr.id)}</strong><small>${esc(adr.id)} · leer decisión y razonamiento</small></span>${ico('arrow')}</button>`}).join(''):empty('No hay ADRs publicados.'),'','arch-adrs')}${planView(p,a)}${p.architecture?section('Resumen original de arquitectura',`<details class="accordion"><summary>Leer el resumen completo, sin recortes</summary>${rich(p.architecture.html)}</details>`):''}</div>`}
function planView(p,a){return `<section id="arch-plan"><div class="row between sectiontitle"><h2>Plan de implementación y documentos</h2><span class="small muted">${p.counts.frds} FRDs · ${p.counts.orders} work orders</span></div>${frdGroups(p).map(group=>{const id=group.match(/^frd-\d+/)[0].toUpperCase(),f=a?.frds?.find(x=>x.id===id),orders=p.orders.filter(w=>w.frd===group),docs=p.docs.filter(d=>d.relPath.startsWith('docs/frds/'+group+'/')&&!d.relPath.includes('/mocks/')&&!d.relPath.includes('/work-orders/'));return `<details class="plan-frd" data-tone="violet"><summary>${id} · ${esc(f?.title||group.replace(/^frd-\d+-/,'').replaceAll('-',' '))} <span class="small muted">· ${orders.length} WO</span></summary><div>${f?.blueprint?`<p style="margin-bottom:var(--s4)">${esc(f.blueprint)}</p>`:''}<div class="row wrap">${docs.map(d=>documentButton(d.id,d.label)).join('')}</div>${orders.map(w=>`<button type="button" class="item-action" data-wo="${esc(w.id)}"><span><strong>${esc(w.id)}</strong><small>${esc(w.title)}</small></span>${pill(stateNames[w.state],stateTones[w.state])}</button>`).join('')||'<p class="small" style="margin-top:var(--s4)">Aún no hay work orders publicados para este FRD.</p>'}</div></details>`}).join('')}</section>`}
function modelView(p){if(p.model.kind!=='ready')return empty(p.model.kind==='none'?'Este proyecto declara que no usa base de datos.':p.model.kind==='error'?'El modelo publicado no se pudo interpretar: '+p.model.message:'Todavía no hay un modelo de datos publicado.');const m=p.model.model;return `<div class="stack"><div class="row between wrap"><span class="small muted">Modelo diseñado · ${m.entities.length} entidades · ${m.relationships.length} relaciones</span><span class="small-note">Fuente: docs/product/data-model.json</span></div><div class="row wrap"><label class="field">${ico('search')}<input id="model-search" type="search" aria-label="Buscar entidad o atributo" placeholder="Buscar entidad o atributo…" value="${esc(modelQuery)}"></label>${tabbar(['Diagrama','Esquema'],model,'model')}</div>${model==='Diagrama'?`<div class="diagram-frame" id="model-frame"><div class="diagram-toolbar"><button class="iconbtn" type="button" data-graph="out" aria-label="Alejar modelo">−</button><span class="small mono" id="model-percent">100%</span><button class="iconbtn" type="button" data-graph="in" aria-label="Acercar modelo">+</button><button class="iconbtn" type="button" data-graph="reset" aria-label="Restablecer vista">↺</button><button class="iconbtn" type="button" data-graph="expand" aria-label="Ampliar modelo">⛶</button></div><div class="diagram-scroll" tabindex="0" aria-label="Diagrama de entidades, desplazable"><div class="diagram-canvas" id="model-canvas">${modelNodes(m)}</div></div></div><p class="small-note">Desplázate por el diagrama o amplíalo. El esquema conserva todos los atributos en texto.</p>`:`<div class="model-entities">${m.entities.filter(entityMatches).map(e=>`<details data-schema="${esc(e.id)}"><summary>${esc(e.name)} <span class="muted small">· ${e.attributes.length} atributos</span></summary><div class="schema">${esc('model '+e.name+' {\n'+e.attributes.map(a=>'  '+a.name+'  '+a.type+(a.optional?'?':'')+'  '+(a.keys||[]).map(k=>'@'+k).join(' ')).join('\n')+'\n}')}</div>${e.description?`<p class="small" style="padding:var(--s4)">${esc(e.description)}</p>`:''}</details>`).join('')}</div>`}<details class="accordion"><summary>Relaciones · ${m.relationships.length}</summary>${m.relationships.map(r=>{const from=m.entities.find(e=>e.id===r.from.entity),to=m.entities.find(e=>e.id===r.to.entity);return `<div class="relation-row"><strong>${esc(from?.name||r.from.entity)}</strong> (${r.from.min}..${r.from.max==='many'?'*':r.from.max}) → <strong>${esc(to?.name||r.to.entity)}</strong> (${r.to.min}..${r.to.max==='many'?'*':r.to.max})${r.name?` · ${esc(r.name)}`:''}${r.description?`<p>${esc(r.description)}</p>`:''}</div>`}).join('')}</details></div>`}
function entityMatches(e){const q=modelQuery.toLowerCase();return !q||(e.name+' '+e.attributes.map(a=>a.name).join(' ')).toLowerCase().includes(q)}
function modelNodes(m){let bottoms=[0,0,0,0,0];return `<svg class="model-lines" id="model-lines" aria-hidden="true"></svg>`+m.entities.filter(entityMatches).map(e=>{const col=bottoms.indexOf(Math.min(...bottoms)),x=col*320+20,y=bottoms[col]+20;bottoms[col]=y+56+e.attributes.length*35+44;return `<article class="model-node ${e.id===modelSelected?'is-active':''}" data-entity="${esc(e.id)}" style="left:${x}px;top:${y}px"><header><button type="button" data-select-entity="${esc(e.id)}" aria-pressed="${e.id===modelSelected}">${esc(e.name)}</button></header>${e.attributes.map(a=>`<div class="model-field" data-field="${esc(a.id)}"><span>${esc(a.name)} ${a.keys?.length?`<span class="model-key">${a.keys.join('·')}</span>`:''}</span><span class="type">${esc(a.type)}${a.optional?'?':''}</span></div>`).join('')}</article>`}).join('')}
function drawModel(){const canvas=$('#model-canvas'),m=contextProject()?.model;if(!canvas||m?.kind!=='ready')return;const cards=[...canvas.querySelectorAll('[data-entity]')];const sizes=cards.map(card=>card.offsetHeight),bottoms=[0,0,0,0,0];cards.forEach((card,index)=>{const col=bottoms.indexOf(Math.min(...bottoms)),top=bottoms[col]+20;card.style.left=(col*320+20)+'px';card.style.top=top+'px';bottoms[col]=top+sizes[index]+40});const height=Math.max(600,...cards.map(el=>el.offsetTop+el.offsetHeight+40));canvas.style.height=height+'px';canvas.style.width='1640px';const svg=$('#model-lines');svg.setAttribute('width','1640');svg.setAttribute('height',String(height));svg.innerHTML=m.model.relationships.map(r=>{const from=cards.find(el=>el.dataset.entity===r.from.entity),to=cards.find(el=>el.dataset.entity===r.to.entity);if(!from||!to)return'';const active=modelSelected&&[r.from.entity,r.to.entity].includes(modelSelected);const x1=from.offsetLeft+from.offsetWidth,y1=from.offsetTop+24,x2=to.offsetLeft,y2=to.offsetTop+24,mx=(x1+x2)/2;return `<path class="${active?'active':''}" d="M ${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}"/>`}).join('');canvas.style.transform=`scale(${modelScale})`;$('#model-percent').textContent=Math.round(modelScale*100)+'%'}
function documentReader(p){if(!p?.docs.length)return empty('No hay documentos publicados para este proyecto.');const selected=p.docs.find(d=>d.id===docId)||getDoc(p,'docs/product/prd.md')||p.docs[0];const groups=[...new Set(p.docs.map(d=>d.group))],type=docType(selected);return `<button type="button" class="btn outline doc-index-toggle" data-action="doc-index" aria-controls="project-doc-index" aria-expanded="false">${ico('book')}Elegir documento · ${p.docs.length}</button><div class="reader-layout"><nav id="project-doc-index" aria-label="Documentos del proyecto"><label class="field" style="margin-bottom:var(--s4)">${ico('search')}<input id="doc-search" type="search" aria-label="Buscar documento" placeholder="Buscar documento…" value="${esc(docQuery)}" style="width:100%"></label>${groups.map(group=>`<div data-doc-group><span class="eyebrow" data-tone="${docGroupTone(group)}">${ico('book')}${esc(group)}</span>${p.docs.filter(d=>d.group===group).map(d=>`<button type="button" data-tone="${documentTypes[docType(d)].tone}" data-doc="${esc(d.id)}" data-doc-match="${esc((d.label+' '+d.relPath).toLowerCase())}" ${d.id===selected.id?'aria-current="page"':''}><span class="doc-type-icon">${ico(documentTypes[docType(d)].icon)}</span><span>${esc(d.label)}</span></button>`).join('')}</div>`).join('')}</nav><article class="document-paper" data-tone="${documentTypes[type].tone}"><div class="doc-actions">${typeBadge(type)}<span class="doc-path">${esc(selected.relPath)}</span><button class="iconbtn" type="button" data-copy-document="${esc(selected.id)}" aria-label="Copiar documento">${ico('copy')}</button></div>${rich(selected.html)}</article></div>`}
function orderDetail(p,w){return `<div class="wo-detail stack"><div class="row between wrap"><button type="button" class="btn ghost" data-action="orders-back">← Work orders</button>${pill(stateNames[w.state],stateTones[w.state])}</div><div><span class="eyebrow">${esc(w.frd)}</span><h2 style="margin-top:var(--s3)">${esc(w.title)}</h2></div><div class="wo-meta"><span class="pill mono">${esc(w.id)}</span><span class="small muted">${esc(w.relPath)}</span></div>${tabbar(['Resumen','Documento completo'],woView,'woview')}${woView==='Documento completo'?`<article class="document-paper" data-tone="blue">${rich(w.html)}</article>`:section('Resumen de la orden',`<p style="color:var(--text)">${esc(w.summary||w.title)}</p>${w.dependsOn?.length?`<h3 style="margin-top:var(--s6)">Depende de</h3><div class="row wrap" style="margin-top:var(--s3)">${w.dependsOn.map(id=>`<button class="btn outline" type="button" data-wo="${esc(id)}">${esc(id)}</button>`).join('')}</div>`:'<p class="small" style="margin-top:var(--s4)">Sin dependencias declaradas.</p>'}<button class="link" type="button" data-woview="Documento completo">Leer contrato, criterios y evidencia ${ico('arrow')}</button>`)}</div>`}
function ordersView(p){if(!p.orders.length)return section('Work orders',`<p>Este proyecto todavía no tiene work orders publicados. Sus documentos de producto y diseño siguen disponibles.</p><div class="row wrap" style="margin-top:var(--s4)">${btn('Ver documentos','open-documents')}${cmd('/pandacorp:architecture')}</div>`);const w=p.orders.find(w=>w.id===woId);if(w)return orderDetail(p,w);return `<div class="toolbar"><label class="field"><select id="wo-frd" aria-label="Filtrar por FRD"><option value="">Todos los FRDs (${new Set(p.orders.map(w=>w.frd)).size})</option>${[...new Set(p.orders.map(w=>w.frd))].sort().map(id=>`<option value="${esc(id)}" ${woFrd===id?'selected':''}>${esc(id)}</option>`).join('')}</select></label><label class="field"><select id="wo-state" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${Object.entries(stateNames).map(([k,v])=>`<option value="${k}" ${woState===k?'selected':''}>${v}</option>`).join('')}</select></label><span class="spacer"></span><span class="small muted" id="wo-count"></span></div><div id="wo-board">${orderBoard(p)}</div>`}
function orderBoard(p){const orders=p.orders.filter(w=>(!woFrd||w.frd===woFrd)&&(!woState||w.state===woState));const states=['todo','in_progress','review','done',...(orders.some(w=>w.state==='fail')?['fail']:[])];return `<div class="board wo-columns">${states.map(state=>`<section class="column" data-tone="${stateTone(state)}"><h2 class="colhead row between"><span>${stateNames[state]}</span>${pill(orders.filter(w=>w.state===state).length,stateTones[state])}</h2>${orders.filter(w=>w.state===state).map(w=>`<button type="button" class="wo-item" data-tone="${stateTone(state)}" data-wo="${esc(w.id)}"><span class="mono accent">${esc(w.id)}</span><strong>${esc(w.title.replace(new RegExp('^'+w.id+'[\\s—:-]*'),''))}</strong><small>${esc(w.frd)}</small>${w.dependsOn?.length?`<small style="margin-top:var(--s2)">↳ ${w.dependsOn.length} dependencias</small>`:''}</button>`).join('')||'<div class="empty small">Sin órdenes en este estado</div>'}</section>`).join('')}</div>`}
function changesView(p){const labels={ready:'Listos',draft:'Borradores',building:'En construcción',closing:'Cerrando',done:'Hechos',discarded:'Descartados'};const items=p.changes?.items||[];return `<div class="stack">${p.changes?.errors?.length?`<div class="hintbox">Hay ${p.changes.errors.length} archivo(s) de cambios que el lector no pudo interpretar. La captura no los cuenta como cambios vacíos.</div>`:''}${['ready','draft','building','closing'].map(state=>section(labels[state],items.filter(x=>x.status===state).map(c=>changeRow(c)).join('')||'<p class="small">Sin cambios en este estado.</p>')).join('')}<details class="accordion"><summary>Historial · ${items.filter(c=>['done','discarded'].includes(c.status)).length} cambios</summary>${items.filter(c=>['done','discarded'].includes(c.status)).map(c=>changeRow(c)).join('')}</details></div>`}
function changeRow(c){return `<button type="button" class="item-action" data-change="${esc(c.id)}"><span><strong>${esc(c.title)}</strong><small>${esc(c.id)} · ${esc(c.date||'Sin fecha')} · ${esc(c.type)}</small></span>${pill(esc(c.status))}${ico('arrow')}</button>`}
function activityView(p){if(!p.activity?.entries?.length)return '<p class="small">No hay entradas de actividad publicadas en la captura.</p>';return p.activity.entries.map(item=>`<div class="relation-row">${typeof item==='string'?esc(item):esc(item.text||item.body||item.message||JSON.stringify(item))}</div>`).join('')}
function partyView(p){return `<div class="stack">${section('La Fragua',`<div class="row between sectiontitle"><strong>${p.running?'Construcción activa':'Equipo en reposo'}</strong>${pill(p.counts.done+'/'+p.counts.orders+' WO')}</div><div class="scene" role="region" tabindex="0" aria-label="La Fragua, escena desplazable"><div class="sceneinner"><div class="line"></div>${[['architect','Arquitectura'],['frontend-dev','Frontend'],['backend-dev','Backend'],['reviewer','Revisión']].map(([name,label])=>`<div class="zone"><img class="agent" src="assets/${name}.png" alt=""><div><strong>${label}</strong><small class="muted">${p.running?'Equipo de construcción':'En reposo'}</small></div></div>`).join('')}</div></div><p class="small-note" style="margin-top:var(--s4)">La escena muestra la composición propuesta. La actividad de esta captura no se transmite en vivo.</p>`)}${section('Bitácora del proyecto',activityView(p))}</div>`}
function observationView(p){return `${tabbar(['Línea de tiempo','DAG'],obs,'obs')}${obs==='DAG'?section('Dependencias de work orders',p.orders.length?p.orders.map(w=>`<div class="dependency-row">${w.dependsOn?.length?`${w.dependsOn.map(id=>`<button class="btn outline" type="button" data-wo="${esc(id)}">${esc(id)}</button>`).join('')}<span aria-hidden="true">→</span>`:'<span class="small muted">Inicio</span>'}<button class="btn" type="button" data-wo="${esc(w.id)}">${esc(w.id)}</button>${pill(stateNames[w.state],stateTones[w.state])}</div>`).join(''):empty('No hay work orders publicados para construir un mapa.')):section('Línea de tiempo',p.timeline?.frds?.length?p.timeline.frds.map(f=>`<details class="plan-frd" data-tone="violet"><summary>${esc(f.label||f.id)} · ${f.workOrders.length} work orders</summary><div>${f.workOrders.map(w=>`<div class="dependency-row"><button class="btn outline" type="button" data-wo="${esc(w.id)}">${esc(w.id)}</button>${pill(stateNames[w.state]||w.state,stateTones[w.state]||'')}<span class="small muted">${w.durationMin!=null?w.durationMin+' min':'Duración no registrada'}</span></div>`).join('')}</div></details>`).join(''):empty('No hay una línea de tiempo registrada para este proyecto.'))}`}
function commandsView(p){return `<div class="stack">${section('Siguiente paso',`<p class="small">Fase registrada: ${esc(phaseLabels[p.phase]||p.phase)}. Los comandos se copian; la maqueta no los ejecuta.</p>${cmd('/pandacorp:'+({product:'design',design:'architecture',architecture:'architecture',implementation:'implement',release:'review-launch'}[p.phase]||'change'))}`)}${section('Comandos a la mano',(p.commands||[]).map(c=>`<div style="margin-bottom:var(--s5)"><p class="small">${esc(c.when)}</p>${cmd(c.command)}</div>`).join('')||'<p>No hay comandos de fase disponibles.</p>')}${section('Cambios y decisiones',cmd('/pandacorp:change')+cmd('/pandacorp:decide'))}</div>`}
function campaign(p){const phases=['discovered','product','design','architecture','implementation','release'],names=['Investigación','Producto','Diseño','Arquitectura','Construcción','Release'];return `<div class="stack"><div class="mini-steps">${phases.map((phase,i)=>`<div class="mini-step ${phase===p.phase?'current':''}"><span class="eyebrow">${i+1}</span><h3 style="margin-top:var(--s3)">${names[i]}</h3><p class="small">${phase===p.phase?'Fase actual':phases.indexOf(p.phase)>i?'Etapa anterior':'Próxima etapa'}</p></div>`).join('')}</div>${commandsView(p)}</div>`}
function workspaceBody(t,p){switch(t){case'Resumen':return summaryView(p);case'Spec':return specView(p);case'Arquitectura':return architecture(p);case'Work orders':return ordersView(p);case'Documentos':return documentReader(p);case'Cambios':return changesView(p);case'Party':return partyView(p);case'Observabilidad':return observationView(p);case'Comandos':return commandsView(p);default:return summaryView(p)}}
function reader(manual){if(!manual)return documentReader(selectedProject());const entries=snapshot.manual||[];const selected=entries.find(d=>d.slug===manualDoc)||entries[0];if(!selected)return empty('No hay páginas de Manual en esta captura.');const style=group=>({concepts:['blue','book'],guides:['teal','flag'],tutorial:['pink','spark'],workflows:['amber','bolt']})[group]||['slate','book'];return `<button type="button" class="btn outline doc-index-toggle" data-action="doc-index" aria-controls="project-doc-index" aria-expanded="false">${ico('book')}Abrir índice · ${entries.length} páginas</button><div class="reader-layout"><nav id="project-doc-index" aria-label="Índice del Manual">${[...new Set(entries.map(d=>d.group))].map(group=>`<div><span class="eyebrow" data-tone="${style(group)[0]}">${ico(style(group)[1])}${esc(group)}</span>${entries.filter(d=>d.group===group).map(d=>`<button type="button" data-tone="${style(group)[0]}" data-manual="${esc(d.slug)}" ${selected.slug===d.slug?'aria-current="page"':''}><span class="doc-type-icon">${ico(style(group)[1])}</span><span>${esc(d.title)}</span></button>`).join('')}</div>`).join('')}</nav><article class="document-paper" data-tone="${style(selected.group)[0]}"><div class="manual-heading"><span class="type-badge">${ico(style(selected.group)[1])}${esc(selected.group)}</span></div>${rich(selected.html)}</article></div>`}
function visualStats(){return `<div class="stack"><div class="stats">${[['Proyectos',projects.length],['FRDs',projects.reduce((n,p)=>n+p.counts.frds,0)],['Work orders',projects.reduce((n,p)=>n+p.counts.orders,0)],['Verificados',projects.reduce((n,p)=>n+p.counts.done,0)]].map(([label,n])=>`<div class="stat"><span class="small muted">${label}</span><div class="number">${n}</div><small>En la captura local</small></div>`).join('')}</div>${section('Avance por proyecto',projects.map(p=>`<div class="projectrow"><div class="row between"><strong>${esc(projectName(p))}</strong><span class="small muted">${p.counts.done}/${p.counts.orders} WO</span></div><div class="track" style="margin-top:var(--s3)"><span style="width:${pct(p)}%"></span></div></div>`).join(''))}</div>`}
function render(){$('#content').dataset.screen=page;$('#content').dataset.project=projectId;$('#content').dataset.tab=tab;const current=page==='idea'?'tablero':page;$('#mainnav').innerHTML=routes.map(([id,label])=>`<a href="#${id}" ${current===id?'aria-current="page"':''}>${label}</a>`).join('');$('#content').innerHTML=({inicio:home,tablero:board,portfolio,idea,propuestas:proposals,logros:achievements,documentacion:()=>head('Documentación','Las guías y conceptos reales de tu fábrica.')+stamp()+reader(true),configuracion:configuration}[page]||home)();document.title=(page==='idea'?selectedIdea().title:titles[page]||'Inicio')+' · Órbita · Ronda 4';if(page==='tablero')filterBoard();afterRender();if(parent!==window)parent.postMessage({source:'mc-prototype',screen:page},location.protocol==='file:'?'*':location.origin)}
function route(){const [screen,query]=location.hash.slice(1).split('?');const q=new URLSearchParams(query||'');page=Object.hasOwn(titles,screen)?screen:'inicio';if(projects.some(p=>p.id===q.get('project')))projectId=q.get('project');if(ideas.some(i=>i.slug===q.get('idea')))ideaSlug=q.get('idea');tab=q.get('tab')||(page==='idea'?'Propuesta':'Resumen');docId=q.get('doc')||'';woId=q.get('wo')||'';woView=q.get('woview')||'Resumen';model=q.get('model')||'Diagrama';obs=q.get('obs')||'Línea de tiempo';$('#mainnav').dataset.open='false';$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Abrir navegación');render()}
function filterBoard(){document.querySelectorAll('[data-idea]').forEach(el=>el.hidden=!(el.dataset.idea.includes(boardQuery.toLowerCase())&&(!boardCategory||el.dataset.category===boardCategory)))}
function afterRender(){document.querySelectorAll('.tabbar').forEach(bar=>{const active=bar.querySelector('[aria-pressed=true]');if(active)bar.scrollLeft+=active.getBoundingClientRect().left-bar.getBoundingClientRect().left-(bar.clientWidth-active.offsetWidth)/2});const p=contextProject();if($('#wo-count')&&p)$('#wo-count').textContent=p.orders.filter(w=>(!woFrd||w.frd===woFrd)&&(!woState||w.state===woState)).length+' órdenes';document.querySelectorAll('.rich h1').forEach(h=>{const replacement=document.createElement('h2');replacement.innerHTML=h.innerHTML;replacement.className=h.className;h.replaceWith(replacement)});document.querySelectorAll('.rich table,.rich pre').forEach(el=>{if(el.scrollWidth>el.clientWidth){el.tabIndex=0;el.setAttribute('role','region');el.setAttribute('aria-label',el.tagName==='TABLE'?'Tabla desplazable':'Código desplazable')}});requestAnimationFrame(drawModel)}
function dialog(title,body){openDialogTrigger=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#detail').showModal();$('#close-dialog').focus();afterRender()}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,2600)}
function openDocument(id){if(!id)return;if(page==='idea')go('idea',{tab:'Documentos',doc:id,wo:''});else go('portfolio',{tab:'Documentos',doc:id,wo:''})}
function openOrder(id){if(!contextProject()?.orders.some(w=>w.id===id)){toast('Esta dependencia no está publicada como work order en la captura.');return}if(page==='idea'){const p=contextProject();go('portfolio',{project:p.id,tab:'Work orders',wo:id,woview:'Resumen',doc:''})}else go('portfolio',{tab:'Work orders',wo:id,woview:'Resumen',doc:''})}
$('#menu').onclick=()=>{const open=$('#mainnav').dataset.open!=='true';$('#mainnav').dataset.open=String(open);$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'Cerrar navegación':'Abrir navegación')};
$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{if(openDialogTrigger?.isConnected)openDialogTrigger.focus()});
$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;$('#theme').textContent=theme==='dark'?'Tema claro':'Tema oscuro'};
$('#font').onchange=e=>document.documentElement.style.setProperty('--heading',e.target.value==='inter'?'Inter':e.target.value==='space'?'Space':'Manrope');
window.addEventListener('hashchange',route);
window.addEventListener('message',event=>{if(parent===window||event.source!==parent||event.data?.source!=='mc-preview')return;const{kind,value}=event.data;if(kind==='theme'&&['light','dark'].includes(value)){document.documentElement.dataset.theme=value;$('#theme').textContent=value==='dark'?'Tema claro':'Tema oscuro'}if(kind==='screen'&&Object.hasOwn(titles,value))go(value,{tab:value==='idea'?'Spec':'Resumen',doc:'',wo:''})});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#mainnav').dataset.open==='true'){$('#mainnav').dataset.open='false';$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Abrir navegación');$('#menu').focus()}if(event.key==='Escape')document.querySelector('.diagram-frame.is-expanded')?.classList.remove('is-expanded')});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='idea-search'){boardQuery=el.value;filterBoard()}if(el.id==='project-search')document.querySelectorAll('[data-project-match]').forEach(x=>x.hidden=!x.dataset.projectMatch.includes(el.value.toLowerCase()));if(el.id==='doc-search'){docQuery=el.value;document.querySelectorAll('[data-doc-match]').forEach(x=>x.hidden=!x.dataset.docMatch.includes(docQuery.toLowerCase()));document.querySelectorAll('[data-doc-group]').forEach(g=>g.hidden=![...g.querySelectorAll('[data-doc-match]')].some(x=>!x.hidden))}if(el.id==='model-search'){modelQuery=el.value;const selection=el.selectionStart;const p=contextProject();const container=el.closest('.panel');container.querySelectorAll('.diagram-frame,.model-entities').forEach(x=>x.remove());const shell=document.createElement('div');shell.innerHTML=modelView(p);const next=shell.querySelector('.diagram-frame,.model-entities');const row=el.closest('.row.wrap');if(next)row.after(next);drawModel();el.focus();el.setSelectionRange(selection,selection)}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='idea-category'){boardCategory=el.value;filterBoard()}if(el.id==='wo-frd'||el.id==='wo-state'){if(el.id==='wo-frd')woFrd=el.value;else woState=el.value;$('#wo-board').innerHTML=orderBoard(selectedProject());afterRender()}});
document.addEventListener('toggle',event=>{const d=event.target;if(d.matches?.('details[data-schema]')&&d.open)document.querySelectorAll('details[data-schema]').forEach(other=>{if(other!==d)other.open=false})},true);
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a');if(!el)return;
 if(el.dataset.scroll){event.preventDefault();document.getElementById(el.dataset.scroll)?.scrollIntoView({block:'start'});return}
 if(el.closest('.rich')&&el.tagName==='A'){let href=el.dataset.docRelPath||el.getAttribute('href')||'';if(href.startsWith('#')){event.preventDefault();const heading=[...el.closest('.rich').querySelectorAll('h2,h3,h4')].find(h=>h.textContent.toLowerCase().replace(/[^a-z0-9 ]/g,'').replaceAll(' ','-')===href.slice(1));heading?.scrollIntoView({block:'start'});return}if(!/^(https?:|mailto:)/.test(href)){event.preventDefault();const p=contextProject()||selectedProject();const current=p.docs.find(d=>d.id===docId)||getDoc(p,'docs/product/prd.md')||p.docs[0];let path=href.split('#')[0];if(!path)return;const base=current?.relPath.split('/').slice(0,-1)||[];if(path.startsWith('/'))path=path.slice(1);else{for(const part of path.split('/')){if(part==='..')base.pop();else if(part!=='.')base.push(part)}path=base.join('/')}const d=p.docs.find(d=>d.relPath===path)||p.docs.find(d=>d.relPath.endsWith('/'+href.split('#')[0]));if(d)openDocument(d.id);else toast('El enlace apunta a un archivo que no está incluido en esta captura.');return}el.target='_blank';el.rel='noopener noreferrer'}
 if(el.dataset.pickProject){$('#detail').close();projectId=el.dataset.pickProject;woFrd='';woState='';docQuery='';modelQuery='';modelScale=1;go('portfolio',{project:projectId,tab:['Resumen','Spec','Work orders','Arquitectura','Cambios','Party','Observabilidad','Documentos','Comandos'].includes(tab)?tab:'Resumen',doc:'',wo:''});return}
 if(el.dataset.tab||el.dataset.section){switchTab(el.dataset.tab||el.dataset.section);return}
 if(el.dataset.model){model=el.dataset.model;go(page,{model});return}
 if(el.dataset.obs){obs=el.dataset.obs;go(page,{obs});return}
 if(el.dataset.doc){openDocument(el.dataset.doc);return}
 if(el.dataset.wo){openOrder(el.dataset.wo);return}
 if(el.dataset.woview){go(page,{woview:el.dataset.woview});return}
 if(el.dataset.frdOrders){woFrd=el.dataset.frdOrders;woState='';if(page==='idea')go('portfolio',{project:contextProject().id,tab:'Work orders',wo:''});else switchTab('Work orders');return}
 if(el.dataset.manual){manualDoc=el.dataset.manual;render();$('.doc-index-toggle')?.focus();return}
 if(el.dataset.adr){const adr=contextProject()?.adrs.find(a=>String(a.id)===el.dataset.adr);if(adr)dialog(adr.title,rich(adr.html));return}
 if(el.dataset.change){const c=contextProject()?.changes?.items.find(c=>c.id===el.dataset.change);if(c)dialog(c.title,`<div class="row wrap sectiontitle">${pill(esc(c.status))}${pill(esc(c.type))}</div>${rich(c.html)}${cmd('/pandacorp:implement change:'+c.id)}`);return}
 if(el.dataset.copy||el.dataset.copyDocument){const value=el.dataset.copy||contextProject()?.docs.find(d=>d.id===el.dataset.copyDocument)?.body||'';try{await navigator.clipboard.writeText(value);toast('Copiado al portapapeles.')}catch{toast('El navegador bloqueó el portapapeles. Puedes seleccionar y copiar el texto.')}return}
 if(el.dataset.star){const on=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',String(on));el.innerHTML=on?'★':ico('star');toast('Favorito cambiado solo en esta maqueta.');return}
 if(el.dataset.selectEntity){modelSelected=modelSelected===el.dataset.selectEntity?'':el.dataset.selectEntity;document.querySelectorAll('[data-entity]').forEach(node=>{const active=node.dataset.entity===modelSelected;node.classList.toggle('is-active',active);node.querySelector('button')?.setAttribute('aria-pressed',String(active))});drawModel();return}
 if(el.dataset.graph){const frame=$('#model-frame');if(el.dataset.graph==='expand'){if(document.fullscreenElement)await document.exitFullscreen();else if(frame.requestFullscreen){try{await frame.requestFullscreen()}catch{frame.classList.toggle('is-expanded')}}else frame.classList.toggle('is-expanded')}else{modelScale=el.dataset.graph==='reset'?1:Math.max(.3,Math.min(2,modelScale+(el.dataset.graph==='in'?.15:-.15)));drawModel()}return}
 const action=el.dataset.action;if(!action)return;
 if(action==='projects'){openPicker();return}
 if(action==='doc-index'){const nav=$('#project-doc-index'),open=nav.dataset.open!=='true';nav.dataset.open=String(open);el.setAttribute('aria-expanded',String(open));return}
 if(action==='orders-back'){go(page,{wo:'',woview:'Resumen'});return}
 const shortcuts={'open-spec':'Spec','open-architecture':'Arquitectura','open-orders':'Work orders','open-documents':'Documentos'};if(shortcuts[action]){switchTab(shortcuts[action]);return}
 if(action==='clear-board'){boardQuery='';boardCategory='';$('#idea-search').value='';$('#idea-category').value='';filterBoard();return}
 if(action==='capture'){dialog('Capturar ideas',`<p>Copia el comando que corresponde a lo que quieres hacer.</p>${['explore','new-idea','discover','recommend'].map(x=>cmd('/pandacorp:'+x)).join('')}`);return}
 if(action==='discarded'){dialog('Ideas descartadas',ideas.filter(i=>i.status==='discarded').map(i=>`<a class="item-action" data-close-on-nav href="${navUrl('idea',{idea:i.slug,tab:'Propuesta'})}"><span><strong>${esc(i.title)}</strong><small>Leer propuesta completa</small></span>${ico('arrow')}</a>`).join(''));return}
 if(['portfolio','tablero','propuestas'].includes(action)){go(action);return}
 if(['agent','reference','lesson','backlog'].includes(action)){dialog(el.querySelector('strong')?.textContent||'Detalle',`<p>Esta ronda completa los recorridos de proyectos y sus documentos. Esta referencia conserva la composición de la ronda anterior.</p>`);return}
 toast('La maqueta no modifica archivos de la fábrica.');
});
document.addEventListener('click',e=>{if(e.target.closest('[data-close-on-nav]'))$('#detail').close()});
const appearance=new URLSearchParams(location.search).get('theme');if(['light','dark'].includes(appearance))document.documentElement.dataset.theme=appearance;
if(new URLSearchParams(location.search).get('demo')==='off')document.querySelectorAll('[data-demo-only]').forEach(el=>el.hidden=true);
route();

document.fonts.ready.then(drawModel);
